const upsertStatusHead = `-- name: UpsertStatusHead :exec
INSERT INTO status_heads (status_id, revision_id, seq, last_revised_at) VALUES (?, ?, ?, ?)
ON CONFLICT (status_id) DO UPDATE SET
  revision_id = excluded.revision_id,
  seq = excluded.seq,
  last_revised_at = excluded.last_revised_at
`

type UpsertStatusHeadParams struct {
	StatusID      string
	RevisionID    string
	Seq           int64
	LastRevisedAt int64
}

func (q *Queries) UpsertStatusHead(ctx context.Context, arg UpsertStatusHeadParams) error {
	_, err := q.db.ExecContext(ctx, upsertStatusHead,
		arg.StatusID,
		arg.RevisionID,
		arg.Seq,
		arg.LastRevisedAt,
	)
	return err
}

const upsertStatusReplyLink = `-- name: UpsertStatusReplyLink :exec
INSERT INTO status_reply_links (status_id, parent_status_id, parent_author_account_id) VALUES (?, ?, ?)
ON CONFLICT (status_id) DO UPDATE SET
  parent_status_id = excluded.parent_status_id,
  parent_author_account_id = excluded.parent_author_account_id
`

type UpsertStatusReplyLinkParams struct {
	StatusID              string
	ParentStatusID        string
	ParentAuthorAccountID string
}

func (q *Queries) UpsertStatusReplyLink(ctx context.Context, arg UpsertStatusReplyLinkParams) error {
	_, err := q.db.ExecContext(ctx, upsertStatusReplyLink, arg.StatusID, arg.ParentStatusID, arg.ParentAuthorAccountID)
	return err
}
